import importlib
import sys

try:
    from importlib.metadata import version as _v

    APP_VERSION = _v("mctp-utils")
except Exception:
    APP_VERSION = "0.0.0+unknown"

# Dictionary mapping utility names to their module names and descriptions
UTILITIES = {
    "mctp_cmd_utils": {
        "module": ".mctp_cmd_utils",
        "description": "MCTP Command Utility",
    },
    "mctp_nsm_utils": {"module": ".mctp_nsm_utils", "description": "MCTP NSM Utility"},
    "mctp_pldm_utils": {
        "module": ".mctp_pldm_utils",
        "description": "MCTP PLDM Utility",
    },
    "mctp_spdm_utils": {
        "module": ".mctp_spdm_utils",
        "description": "MCTP SPDM Utility",
    },
    "mctp_vdm_utils": {"module": ".mctp_vdm_utils", "description": "MCTP VDM Utility"},
    "mfghelper": {
        "module": ".mfghelper",
        "description": "Manufacturing Helper Utility",
    },
}


def print_help():
    print("Error: Utility name is required")
    print("Valid utility names are:")
    for name, info in UTILITIES.items():
        print(f"    {name:<24} {info['description']}")


def main():
    # Handle insufficient arguments
    if len(sys.argv) < 2:
        print_help()
        sys.exit(1)

    utility_name = sys.argv[1]

    # Handle version request
    if utility_name == "--version":
        print(f"mctp_utils {APP_VERSION}")
        sys.exit(0)

    # Check if utility exists
    if utility_name not in UTILITIES:
        print_help()
        sys.exit(1)

    # Load the requested utility module
    try:
        util = importlib.import_module(
            UTILITIES[utility_name]["module"], package="mctp_utils"
        )
    except ImportError as e:
        print(f"Error: Failed to import utility '{utility_name}': {e}")
        sys.exit(1)

    # Remove the utility name from the command line arguments
    sys.argv.pop(1)

    # Pass the remaining arguments to the sub-utility
    util.main()


if __name__ == "__main__":
    main()

