        {
            "position": [4, 5],
            "name": "EID Assignment Status",
            "bit_def": EID_ASSIGNMENT_STATUS_DEF,
        },
    ]
    EID_POOL_SIZE_DEF = {0x00: "NO_DYNAMIC_EID_POOL"}
