def main():
    # parse argument
    parser = argparse.ArgumentParser(
        description=f"NVIDIA MCTP CMD Utility v{APP_VERSION}"
    )
    parser.add_argument(
        "--version", action="version", version=f"%(prog)s {APP_VERSION}"
    )
    parser.add_argument(
        "--binding",
        "-b",
        required=False,
        choices=["usb", "smbus", "spb", "mq"],
        default="usb",
        help="binding",
    )
    parser.add_argument(
        "--mctpapp",
        required=False,
        default=Path("~/mcxn236/bin/mctpapp"),
        help="mctpapp path",
    )
    parser.add_argument(
        "--dst_eid",
        "-d",
        required=False,
        default=0,
        type=lambda x: int(x, 0),
        help="destination EID",
    )
    parser.add_argument(
        "--src_eid",
        "-s",
        required=False,
        default=50,
        type=lambda x: int(x, 0),
        help="source EID",
    )
    parser.add_argument(
        "--usb_vid",
        required=False,
        default=0x0955,
        type=lambda x: int(x, 0),
        help="usb device VID",
    )
    parser.add_argument(
        "--usb_pid",
        "-p",
        required=False,
        default=0,
        type=lambda x: int(x, 0),
        help="usb device PID",
    )
    parser.add_argument(
        "--bus_num",
        required=False,
        default=0,
        type=lambda x: int(x, 0),
        help="usb bus number",
    )
    parser.add_argument(
        "--dev_num",
        required=False,
        default=0,
        type=lambda x: int(x, 0),
        help="usb device number",
    )
    parser.add_argument(
        "--verbose", "-v", action="count", default=0, help="verbose output"
    )
    parser.add_argument(
        "--truncate_len",
        "-t",
        required=False,
        default=-1,
        type=int,
        help="[FOR LOG ONLY] Max length needed for log. Will truncate if the log exceeeds this length. Default as -1 to not truncate.",
    )
    parser.add_argument(
        "--tcp_port",
        required=False,
        default=5000,
        type=int,
        help="TCP port number (default: 5000)",
    )
    parser.add_argument(
        "--max_payload",
        required=False,
        default=64,
        type=int,
        help="Max payload size for MCTP packets (not including the header)",
    )
    parser.add_argument("--client", action="store_true", help="only run as client")

    subparsers = parser.add_subparsers(dest="cmd")
    for handler in HANDLER_DICT.values():
        handler.add_parser(subparsers)
    args = parser.parse_args()
    if args.cmd is None:
        parser.print_help()
        sys.exit(1)
    # set logger
    log_format = "%(asctime)-15s %(levelname)-10s %(name)-20s %(message)s"
    log_level = logging.WARNING
    if args.verbose == 1:
        log_level = logging.INFO
    elif args.verbose > 1:
        log_level = logging.DEBUG
    logging.basicConfig(level=log_level, format=log_format)

    ByteFormatter.configure(args.truncate_len)

    if args.binding == "usb":
        if not args.client:
            MctpTCPServer(
                MctpUsbTransportLayer(
                    vid=args.usb_vid,
                    pid=args.usb_pid,
                    bus_number=args.bus_num,
                    device_number=args.dev_num,
                ),
                port=args.tcp_port,
                max_payload_size=args.max_payload,
            ).start(background=True)
        client = TCPClient(args.src_eid, args.dst_eid, port=args.tcp_port)
    elif args.binding == "mq":
        if not args.client:
            MctpTCPServer(
                MctpMQTransportLayer(),
                port=args.tcp_port,
                max_payload_size=args.max_payload,
            ).start(background=True)
        client = TCPClient(args.src_eid, args.dst_eid, port=args.tcp_port)
    elif args.binding == "smbus":
        if not args.client:
            MctpAppServer(args.mctpapp, args.src_eid, args.binding).start(
                background=True
            )
        client = SmbClient(args.src_eid, args.dst_eid, MESSAGE_TYPE)
    elif args.binding == "spb":
        if not args.client:
            MctpAppServer(args.mctpapp, args.src_eid, args.binding).start(
                background=True
            )
        client = SmbClient(args.src_eid, args.dst_eid, MESSAGE_TYPE)
    else:
        raise ValueError(f"unknown binding {args.binding}")

    exit_code = 0
    try:
        output = HANDLER_DICT[args.cmd].handle(client, args)
        print(output)
    except MctpException as e:
        print(f"[main] Error: {e}")
        exit_code = e.exit_code
    except BaseException as e:
        print(f"[main] Error: {e}")
        traceback.print_exc()
        exit_code = 1
    finally:
        client.close()

    sys.exit(exit_code)


if __name__ == "__main__":
    main()
